  1943	md_is_link_label(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines, OFF beg,
  1944	                 OFF* p_end, MD_SIZE* p_beg_line_index, MD_SIZE* p_end_line_index,
  1945	                 OFF* p_contents_beg, OFF* p_contents_end)
  1946	{
  1947	    OFF off = beg;
  1948	    OFF contents_beg = 0;
  1949	    OFF contents_end = 0;
  1950	    MD_SIZE line_index = 0;
  1951	    int len = 0;
  1952	
  1953	    *p_beg_line_index = 0;
  1954	
  1955	    if(CH(off) != _T('['))
  1956	        return FALSE;
  1957	    off++;
  1958	
  1959	    while(1) {
  1960	        OFF line_end = lines[line_index].end;
  1961	
  1962	        while(off < line_end) {
  1963	            if(CH(off) == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
  1964	                if(contents_end == 0) {
  1965	                    contents_beg = off;
  1966	                    *p_beg_line_index = line_index;
  1967	                }
  1968	                contents_end = off + 2;
  1969	                off += 2;
  1970	            } else if(CH(off) == _T('[')) {
  1971	                return FALSE;
  1972	            } else if(CH(off) == _T(']')) {
  1973	                if(contents_beg < contents_end) {
  1974	                    /* Success. */
  1975	                    *p_contents_beg = contents_beg;
  1976	                    *p_contents_end = contents_end;
  1977	                    *p_end = off+1;
  1978	                    *p_end_line_index = line_index;
  1979	                    return TRUE;
  1980	                } else {
  1981	                    /* Link label must have some non-whitespace contents. */
  1982	                    return FALSE;
  1983	                }
  1984	            } else {
  1985	                unsigned codepoint;
  1986	                SZ char_size;
  1987	
  1988	                codepoint = md_decode_unicode(ctx->text, off, ctx->size, &char_size);
  1989	                if(!ISUNICODEWHITESPACE_(codepoint)) {
  1990	                    if(contents_end == 0) {
  1991	                        contents_beg = off;
  1992	                        *p_beg_line_index = line_index;
  1993	                    }
  1994	                    contents_end = off + char_size;
  1995	                }
  1996	
  1997	                off += char_size;
  1998	            }
  1999	
  2000	            len++;
  2001	            if(len > 999)
  2002	                return FALSE;
  2003	        }
  2004	
  2005	        line_index++;
  2006	        len++;
  2007	        if(line_index < n_lines)
  2008	            off = lines[line_index].beg;
  2009	        else
  2010	            break;
  2011	    }
  2012	
  2013	    return FALSE;
  2014	}
